/**
 * The scenario mirror (utils/scenarios.ts): checked against the API on every case of the shared
 * fixture (generated by the API's real apply_scenario, never by hand), and its editing rules:
 * an edit in a scenario becomes its changes, shared labels or a refusal; base edits carry pipe
 * changes with their pipes (by identity, through every graph edit); the valve-type rule; new ids
 * never take a changed element's id.
 */
import { describe, expect, it } from 'vitest';
import type { Component, Override, PipeDefinition, Project, Scenario } from '../api/types';
import openapi from '../api/openapi.json';
import fixture from './__fixtures__/scenario-cases.json';
import { deepFreeze, enteredFor } from '../testing/helpers';
import {
	addBranch,
	connectPorts,
	deleteComponent,
	disconnect,
	insertComponentInConnection,
	plugPort,
	reversePiping,
	updateComponent,
	updateConnection
} from './edit';
import { pumpTransferExample } from './examples';
import { changeCategory } from './export/tables';
import { COMPONENT_KINDS, createComponent, newId, usedIds } from './factory';
import { variableSpec } from './goal-seek';
import { componentSchemaName, GOAL_VARIABLE_FIELDS, OVERRIDE_FIELDS } from './model-rules';
import { canonicalJson } from './json';
import { addPipe, removePipe, updatePipe, withMaterial } from './piping';
import { scenarioProblems } from './scenario-problems';
import {
	applyScenario,
	carryChanges,
	caseKey,
	caseProject,
	changeFieldLabel,
	changeValueText,
	copyName,
	fieldLabelFor,
	makeOverride,
	type ChangeTarget,
	lapsedChanges,
	MAX_CHANGES,
	newScenarioId,
	overlappingChanges,
	scenarioEdit,
	setValue,
	trackPipes,
	valueOf,
	withChange,
	withoutChange,
	withScenarios
} from './scenarios';
import { displayUnit, formatValue, SI_UNITS, unitLabel } from './units';
import { parseProject, referenceProblems, schemaProblems } from './validate';

interface FixtureCase {
	kind: 'applied' | 'invalid' | 'not_found' | 'rejected';
	name: string;
	project: Project;
	scenarioId?: string;
	expected?: {
		project: Project;
		overrides: { index: number; state: string; value: unknown; baseValue: unknown }[];
	};
	issues?: { message: string }[];
}

const CASES = (fixture as unknown as { cases: FixtureCase[] }).cases;

/** The fixture's project (API JSON with its set fields only) with the schema's defaults filled. */
function filled(project: Project): Project {
	return parseProject(structuredClone(project));
}

describe('the shared fixture (generated by the API)', () => {
	it('has every kind of case', () => {
		expect(new Set(CASES.map((c) => c.kind))).toEqual(
			new Set(['applied', 'invalid', 'not_found', 'rejected'])
		);
	});

	for (const c of CASES.filter((c) => c.kind === 'applied')) {
		it(`applies a scenario as the API does: ${c.name}`, () => {
			const applied = applyScenario(c.project, c.scenarioId!);
			expect(applied.project).toEqual(c.expected!.project);
			expect(applied.changes.map((s) => [s.index, s.state])).toEqual(
				c.expected!.overrides.map((o) => [o.index, o.state])
			);
			// Values and base values, on the project as the app holds it (defaults filled).
			const project = filled(c.project);
			const effective = applyScenario(project, c.scenarioId!).project;
			const scenario = project.scenarios!.find((s) => s.id === c.scenarioId)!;
			for (const record of c.expected!.overrides) {
				if (record.state !== 'applied') continue;
				const override = scenario.overrides![record.index]!;
				const target =
					override.kind === 'component'
						? ({ kind: 'component', componentId: override.componentId } as const)
						: override.kind === 'pipe'
							? ({
									kind: 'pipe',
									connectionId: override.connectionId,
									pipeIndex: override.pipeIndex
								} as const)
							: ({ kind: 'project' } as const);
				expect(valueOf(project, target, override.field), `base ${record.index}`).toEqual(
					record.baseValue
				);
				expect(valueOf(effective, target, override.field), `value ${record.index}`).toEqual(
					record.value
				);
			}
		});
	}

	for (const c of CASES.filter((c) => c.kind === 'invalid')) {
		it(`finds the values the API rejects, at the same changes: ${c.name}`, () => {
			const rejected = new Set(
				c.issues!.map((i) => Number(/\.overrides\.(\d+)/.exec(i.message)?.[1] ?? NaN))
			);
			const found = scenarioProblems(filled(c.project), c.scenarioId!);
			const located = new Set(found.map((p) => p.index));
			for (const index of rejected) expect(located, `change ${index}`).toContain(index);
			for (const index of located) if (index !== null) expect(rejected).toContain(index);
		});
	}

	for (const c of CASES.filter((c) => c.kind === 'not_found')) {
		it(`knows an unknown scenario id: ${c.name}`, () => {
			expect(applyScenario(c.project, c.scenarioId!).scenario).toBeUndefined();
			expect(caseProject(c.project, c.scenarioId!)).toBe(c.project);
		});
	}

	for (const c of CASES.filter((c) => c.kind === 'rejected')) {
		it(`rejects the structures the API rejects: ${c.name}`, () => {
			const schema = schemaProblems(c.project);
			const problems = schema.length ? schema : referenceProblems(c.project);
			expect(problems.length).toBeGreaterThan(0);
			// The same project without its scenarios is fine: the problems are the scenarios'.
			const plain = withScenarios(c.project, []);
			expect([...schemaProblems(plain), ...referenceProblems(plain)]).toEqual([]);
		});
	}
});

/** The transfer example with one scenario `S1` named Winter holding `overrides`. */
function withScenario(overrides: Override[] = [], project = pumpTransferExample()): Project {
	return deepFreeze({
		...project,
		scenarios: [{ id: 'S1', name: 'Winter', overrides }]
	});
}

const P1 = { kind: 'component', componentId: 'P1' } as const;
const R1 = { kind: 'component', componentId: 'R1' } as const;

/** Edit the case S1 of `project` with `change`, apply it to a copy of the base, return the base. */
function editIn(project: Project, change: (draft: Project) => Project | void): Project {
	const edit = scenarioEdit(project, 'S1', change);
	if (!edit.ok) throw new Error(edit.reason);
	const draft = structuredClone(project);
	edit.apply(draft);
	return draft;
}

describe('editing in a scenario', () => {
	it('records an allow-listed value as a change, and typing the base value back removes it', () => {
		const project = withScenario();
		const off = editIn(project, (p) =>
			updateComponent(p, 'P1', (c) => ({ ...c, status: 'off' }) as typeof c)
		);
		expect(off.scenarios![0]!.overrides).toEqual([
			{ kind: 'component', componentId: 'P1', field: 'status', value: 'off' }
		]);
		// The base is unchanged.
		expect(off.components).toEqual(project.components);
		expect(caseProject(off, 'S1').components[1]).toMatchObject({ status: 'off' });
		const back = editIn(deepFreeze(off), (p) =>
			updateComponent(p, 'P1', (c) => ({ ...c, status: 'on' }) as typeof c)
		);
		expect(back.scenarios![0]!.overrides).toEqual([]);
	});

	it('makes one spec change of a material change, and one length change', () => {
		const project = withScenario();
		const stainless = {
			id: 'stainless_steel',
			name: 'Stainless steel',
			schedules: [
				{
					id: '40S',
					sizes: [
						{
							nominalSize: project.connections[2]!.piping.pipes[0]!.nominalSize,
							nps: '3',
							innerDiameter: 0.0779,
							roughness: 1e-5
						}
					]
				}
			]
		} as never;
		const next = editIn(project, (p) =>
			updateConnection(p, 'L3', (c) => ({
				...c,
				piping: updatePipe(c.piping, 0, (pipe) => ({
					...withMaterial(pipe, stainless),
					length: 80
				}))
			}))
		);
		const size = project.connections[2]!.piping.pipes[0]!.nominalSize; // NPS 3, kept
		expect(next.scenarios![0]!.overrides).toHaveLength(2);
		expect(next.scenarios![0]!.overrides).toEqual(
			expect.arrayContaining([
				{
					kind: 'pipe',
					connectionId: 'L3',
					pipeIndex: 0,
					field: 'spec',
					value: { materialId: 'stainless_steel', schedule: '40S', nominalSize: size }
				},
				{ kind: 'pipe', connectionId: 'L3', pipeIndex: 0, field: 'length', value: 80 }
			])
		);
		expect(next.connections).toEqual(project.connections);
	});

	it('records a temperature-only fluid change as fluid.temperature, any other as the whole fluid', () => {
		const project = withScenario();
		const cold = editIn(project, (p) => {
			p.fluid = { kind: 'builtin', fluidId: 'water', temperature: 278.15 };
		});
		expect(cold.scenarios![0]!.overrides).toEqual([
			{ kind: 'project', field: 'fluid.temperature', value: 278.15 }
		]);
		const glycol = editIn(deepFreeze(cold), (p) => {
			p.fluid = {
				kind: 'builtin',
				fluidId: 'ethylene_glycol',
				temperature: 278.15,
				concentration: 0.3
			};
		});
		// The whole fluid replaces the temperature change, in its place.
		expect(glycol.scenarios![0]!.overrides).toEqual([
			{
				kind: 'project',
				field: 'fluid',
				value: {
					kind: 'builtin',
					fluidId: 'ethylene_glycol',
					temperature: 278.15,
					concentration: 0.3
				}
			}
		]);
		expect(overlappingChanges(glycol.scenarios![0]!.overrides!)).toEqual([]);
		// While a whole-fluid change exists, a temperature edit updates it.
		const warmer = editIn(deepFreeze(glycol), (p) => {
			if (p.fluid.kind === 'builtin') p.fluid.temperature = 283.15;
		});
		expect(warmer.scenarios![0]!.overrides).toEqual([
			{
				kind: 'project',
				field: 'fluid',
				value: {
					kind: 'builtin',
					fluidId: 'ethylene_glycol',
					temperature: 283.15,
					concentration: 0.3
				}
			}
		]);
		// Back to the base fluid: no change left.
		const base = editIn(deepFreeze(warmer), (p) => {
			p.fluid = structuredClone(project.fluid);
		});
		expect(base.scenarios![0]!.overrides).toEqual([]);
	});

	it('applies names, the project name and description and units to the base (shared)', () => {
		const project = withScenario([
			{ kind: 'component', componentId: 'P1', field: 'status', value: 'off' }
		]);
		const next = editIn(project, (p) => {
			p.components[1]!.name = 'Main pump';
			p.metadata.name = 'Renamed';
			p.settings.units = { ...p.settings.units, flow: 'gpm' };
		});
		expect(next.components[1]!.name).toBe('Main pump');
		expect(next.metadata.name).toBe('Renamed');
		expect(next.settings.units.flow).toBe('gpm');
		expect(next.scenarios![0]!.overrides).toHaveLength(1);
	});

	it('refuses topology and locked values', () => {
		const project = withScenario();
		const refused = [
			(p: Project) => deleteComponent(p, 'V1', { join: true }),
			(p: Project) => addBranch(p, 'L2'),
			(p: Project) => disconnect(p, 'L1'),
			(p: Project) => updateComponent(p, 'P1', (c) => ({ ...c, elevation: 2 })),
			(p: Project) => updateConnection(p, 'L1', (c) => ({ ...c, piping: addPipe(c.piping) })),
			(p: Project) =>
				updateConnection(p, 'L1', (c) => ({ ...c, piping: { ...c.piping, fittings: [] } })),
			(p: Project) => {
				p.settings.siteElevation = 500;
			},
			(p: Project) => {
				p.pumpLibrary[0]!.name = 'Other';
			},
			(p: Project) =>
				updateComponent(p, 'P1', (c) => ({
					...c,
					control: { mode: 'flow', setpoint: 0.01, minSpeed: 0.5 }
				}))
		];
		for (const change of refused) {
			expect(scenarioEdit(project, 'S1', change)).toMatchObject({ ok: false, reason: 'refused' });
		}
	});

	it(`refuses a new change beyond ${MAX_CHANGES}, and keeps editing existing ones`, () => {
		const many: Override[] = Array.from({ length: MAX_CHANGES }, (_, i) => ({
			kind: 'component',
			componentId: `X${i}`,
			field: 'status',
			value: 'off'
		}));
		const project = withScenario(many);
		expect(
			scenarioEdit(project, 'S1', (p) =>
				updateComponent(p, 'P1', (c) => ({ ...c, status: 'off' }) as typeof c)
			)
		).toMatchObject({ ok: false, reason: 'limit' });
		const full = withScenario([
			...many.slice(1),
			{ kind: 'component', componentId: 'R1', field: 'liquidLevel', value: 4 }
		]);
		expect(
			scenarioEdit(full, 'S1', (p) =>
				updateComponent(p, 'R1', (c) => ({ ...c, liquidLevel: 5 }) as typeof c)
			).ok
		).toBe(true);
	});
});

describe('setValue, the inverse of valueOf (goal seek writes values found into the base)', () => {
	it('writes each kind of value where valueOf reads it, and refuses a missing target', () => {
		const draft = structuredClone(pumpTransferExample());
		const writes: [Parameters<typeof setValue>[1], string, unknown][] = [
			[{ kind: 'component', componentId: 'P1' }, 'speed', 0.8611744213850658],
			[{ kind: 'component', componentId: 'R1' }, 'liquidLevel', 4.25],
			[{ kind: 'component', componentId: 'V1' }, 'resistance', { kind: 'Cv', value: 18.2 }],
			[{ kind: 'pipe', connectionId: 'L3', pipeIndex: 0 }, 'length', 41.3],
			[{ kind: 'project' }, 'fluid.temperature', 301.2]
		];
		for (const [target, field, value] of writes) {
			expect(setValue(draft, target, field, value)).toBe(true);
			expect(valueOf(draft, target, field)).toEqual(value);
		}
		expect(draft.components.find((c) => c.id === 'P1')).toMatchObject({
			speed: 0.8611744213850658
		});
		// No flow control to hold a setpoint, and no such component: nothing is written.
		const before = canonicalJson(draft);
		expect(setValue(draft, { kind: 'component', componentId: 'P1' }, 'control.setpoint', 1)).toBe(
			false
		);
		expect(setValue(draft, { kind: 'component', componentId: 'P9' }, 'speed', 1)).toBe(false);
		expect(canonicalJson(draft)).toBe(before);
	});
});

describe('changes and their states', () => {
	it('keeps a change whose target is gone, and says it no longer applies', () => {
		const project = withScenario([
			{ kind: 'component', componentId: 'V1', field: 'status', value: 'isolated' },
			{ kind: 'component', componentId: 'P1', field: 'control.setpoint', value: 0.01 },
			{ kind: 'project', field: 'fluid.temperature', value: 280 }
		]);
		const deleted = deleteComponent(project, 'V1', { join: true });
		expect(lapsedChanges(deleted, 'S1').map((c) => [c.index, c.state])).toEqual([
			[0, 'orphaned'],
			[1, 'not_applicable']
		]);
		const custom = {
			...project,
			fluid: { kind: 'custom', name: 'Brine', density: 1100, dynamicViscosity: 0.002 }
		} as Project;
		expect(lapsedChanges(custom, 'S1').map((c) => c.state)).toEqual([
			'not_applicable',
			'not_applicable'
		]);
	});

	it('withChange replaces in place, withoutChange removes; caseKey follows changes only', () => {
		let scenario: Scenario = { id: 'S1', name: 'Winter', overrides: [] };
		scenario = withChange(scenario, {
			kind: 'component',
			componentId: 'R1',
			field: 'liquidLevel',
			value: 4
		});
		scenario = withChange(scenario, {
			kind: 'component',
			componentId: 'P1',
			field: 'status',
			value: 'off'
		});
		scenario = withChange(scenario, {
			kind: 'component',
			componentId: 'R1',
			field: 'liquidLevel',
			value: 5
		});
		expect(scenario.overrides!.map((o) => o.value)).toEqual([5, 'off']);
		expect(withoutChange(scenario, R1, 'liquidLevel').overrides).toHaveLength(1);
		const project = withScenarios(pumpTransferExample(), [scenario]);
		const renamed = withScenarios(project, [{ ...scenario, name: 'Cold' }]);
		expect(caseKey(renamed, 'S1', 'f')).toBe(caseKey(project, 'S1', 'f'));
		expect(caseKey(project, null, 'f')).toBe('f');
		expect(caseKey(project, 'S9', 'f')).toBeNull();
		expect(
			caseKey(withScenarios(project, [withoutChange(scenario, P1, 'status')]), 'S1', 'f')
		).not.toBe(caseKey(project, 'S1', 'f'));
	});

	it('names new scenarios and copies', () => {
		const project = withScenario();
		expect(newScenarioId(project)).toBe('S2');
		expect(copyName('Winter')).toBe('Winter (copy)');
		expect(copyName('x'.repeat(100))).toHaveLength(100);
		expect(
			changeValueText(
				project,
				{ kind: 'component', componentId: 'P1', field: 'speed', value: 0.9 },
				0.9,
				SI_UNITS
			)
		).toBe('90 %');
		expect(
			changeValueText(
				project,
				{ kind: 'component', componentId: 'V1', field: 'status', value: 'isolated' },
				'isolated',
				SI_UNITS
			)
		).toBe('Closed (isolated)');
		expect(
			changeValueText(
				project,
				{ kind: 'component', componentId: 'V1', field: 'resistance', value: null },
				null,
				SI_UNITS
			)
		).toBe('Default');
	});

	it('new ids never take the id of a deleted element whose changes are kept', () => {
		const project = withScenario([
			{ kind: 'component', componentId: 'P2', field: 'status', value: 'off' }
		]);
		expect(usedIds(project).has('P2')).toBe(true);
		expect(newId(project, 'P')).toBe('P3');
	});
});

describe('base edits carry pipe changes with their pipes (identity)', () => {
	/**
	 * A project whose every pipe has a distinct length (a marker) and a spec change in S1 that
	 * names it by that length: after an edit, every change must be on the pipe with its marker.
	 */
	function marked(project: Project): Project {
		let length = 1;
		const overrides: Override[] = [];
		const connections = project.connections.map((c) => ({
			...c,
			piping: {
				...c.piping,
				pipes: c.piping.pipes.map((p, i) => {
					const marker = length++;
					overrides.push({
						kind: 'pipe',
						connectionId: c.id,
						pipeIndex: i,
						field: 'spec',
						value: { materialId: 'custom', innerDiameter: 0.1, roughness: marker * 1e-6 }
					});
					return { ...p, length: marker };
				})
			}
		}));
		return deepFreeze({
			...project,
			connections,
			scenarios: [{ id: 'S1', name: 'Winter', overrides }]
		});
	}

	/** Two pipes per connection, so moves within connections show. */
	function twoPipes(): Project {
		const project = pumpTransferExample();
		return {
			...project,
			connections: project.connections.map((c) => ({ ...c, piping: addPipe(c.piping) }))
		};
	}

	/** Apply `change` as the store does: a draft copy, tracked, then carried. */
	function carry(project: Project, change: (draft: Project) => Project | void) {
		const draft = structuredClone(project);
		const tracker = trackPipes(project, draft);
		const next = change(draft) ?? draft;
		return carryChanges(project, tracker, next);
	}

	function expectOnMarkers(project: Project) {
		for (const o of project.scenarios![0]!.overrides!) {
			if (o.kind !== 'pipe') continue;
			const pipe = project.connections.find((c) => c.id === o.connectionId)?.piping.pipes[
				o.pipeIndex
			] as PipeDefinition | undefined;
			if (!pipe) continue; // kept, no longer applies
			const marker = Math.round(((o.value as { roughness: number }).roughness ?? 0) / 1e-6);
			expect(pipe.length, `${o.connectionId} pipe ${o.pipeIndex}`).toBe(marker);
		}
	}

	const valve = (project: Project) => createComponent('gate', project);

	const EDITS: [string, (p: Project) => Project, (before: Project, after: Project) => void][] = [
		[
			'insert into a connection drawn with the flow',
			(p) => insertComponentInConnection(p, 'L2', valve(p)),
			(_, after) => expect(after.scenarios![0]!.overrides).toHaveLength(6)
		],
		[
			'insert into a connection drawn against the flow (turned around, pipes reversed)',
			(p) => {
				const turned = updateConnection(p, 'L1', (c) => c);
				const against = {
					...turned,
					connections: turned.connections.map((c) =>
						c.id === 'L1'
							? {
									...c,
									fromComponentId: 'P1',
									fromPortId: 'suction',
									toComponentId: 'R1',
									toPortId: 'port_1',
									piping: reversePiping(c.piping)
								}
							: c
					)
				};
				return insertComponentInConnection(against, 'L1', valve(against));
			},
			() => {}
		],
		['add a branch', (p) => addBranch(p, 'L3'), () => {}],
		[
			'delete with join',
			(p) => deleteComponent(p, 'V1', { join: true }),
			(_, after) => {
				const merged = after.connections.find((c) => c.id === 'L2')!;
				expect(merged.piping.pipes).toHaveLength(4);
			}
		],
		[
			'delete without join (the connections go; their changes are kept)',
			(p) => deleteComponent(p, 'V1'),
			(_, after) => expect(after.scenarios![0]!.overrides).toHaveLength(6)
		],
		[
			'remove the first pipe',
			(p) => updateConnection(p, 'L3', (c) => ({ ...c, piping: removePipe(c.piping, 0) })),
			(_, after) => expect(after.scenarios![0]!.overrides).toHaveLength(5)
		],
		[
			'remove the last pipe',
			(p) => updateConnection(p, 'L3', (c) => ({ ...c, piping: removePipe(c.piping, 1) })),
			(_, after) => expect(after.scenarios![0]!.overrides).toHaveLength(5)
		],
		[
			'reverse the piping',
			(p) => updateConnection(p, 'L2', (c) => ({ ...c, piping: reversePiping(c.piping) })),
			() => {}
		],
		[
			'disconnect',
			(p) => disconnect(p, 'L2'),
			(_, after) => expect(after.scenarios![0]!.overrides).toHaveLength(6)
		],
		['plug a port', (p) => plugPort(disconnect(p, 'L3'), 'V1', 'outlet'), () => {}],
		[
			'edit a pipe in place',
			(p) =>
				updateConnection(p, 'L1', (c) => ({
					...c,
					piping: updatePipe(c.piping, 1, (x) => ({ ...x, length: 2 }))
				})),
			() => {}
		]
	];

	for (const [name, edit, check] of EDITS) {
		it(name, () => {
			const project = marked(twoPipes());
			const { project: after } = carry(project, edit);
			if (name !== 'edit a pipe in place') expectOnMarkers(after);
			check(project, after);
			// Every change still names a distinct (target, field).
			const keys = after.scenarios![0]!.overrides!.map((o) =>
				canonicalJson([
					o.kind,
					(o as { connectionId?: string }).connectionId,
					(o as { pipeIndex?: number }).pipeIndex,
					o.field
				])
			);
			expect(new Set(keys).size).toBe(keys.length);
		});
	}

	it('a removed pipe takes its changes with it, with a note; undo is the old project', () => {
		const project = marked(twoPipes());
		const { project: after, notes } = carry(project, (p) =>
			updateConnection(p, 'L3', (c) => ({ ...c, piping: removePipe(c.piping, 0) }))
		);
		const l3 = after.scenarios![0]!.overrides!.filter(
			(o) => o.kind === 'pipe' && o.connectionId === 'L3'
		);
		expect(l3).toEqual([
			expect.objectContaining({ pipeIndex: 0, value: expect.objectContaining({ roughness: 6e-6 }) })
		]);
		expect(notes[0]).toMatch(/^Pipe 1 of connection L3 removed, with its changes in Winter/);
	});

	it('a pressure ↔ flow valve change removes that valve’s setpoint changes, with a note', () => {
		const project = pumpTransferExample();
		const prv = createComponent('prv', project);
		const withPrv = insertComponentInConnection(project, 'L2', prv);
		const scenario: Scenario = {
			id: 'S1',
			name: 'Winter',
			overrides: [
				{ kind: 'component', componentId: prv.id, field: 'setpoint', value: 150000 },
				{ kind: 'component', componentId: prv.id, field: 'status', value: 'failed_open' }
			]
		};
		const base = deepFreeze(withScenarios(withPrv, [scenario]));
		const toFcv = carry(base, (p) =>
			updateComponent(p, prv.id, (c) => ({ ...c, valveType: 'fcv', setpoint: 0 }) as typeof c)
		);
		expect(toFcv.project.scenarios![0]!.overrides).toEqual([scenario.overrides![1]]);
		expect(toFcv.notes[0]).toMatch(/setpoint changes of .* in Winter were removed/);
		const toPsv = carry(base, (p) =>
			updateComponent(p, prv.id, (c) => ({ ...c, valveType: 'psv' }) as typeof c)
		);
		expect(toPsv.project.scenarios![0]!.overrides).toEqual(scenario.overrides);
	});

	it('connecting ports or editing a component leaves changes as they are', () => {
		const project = marked(twoPipes());
		const disconnected = deepFreeze(disconnect(project, 'L3'));
		const { project: after } = carry(disconnected, (p) =>
			connectPorts(
				p,
				{ componentId: 'V1', portId: 'outlet' },
				{ componentId: 'R2', portId: 'port_1' }
			)
		);
		expect(after.scenarios).toEqual(disconnected.scenarios);
	});
});

describe('what a scenario says about its values', () => {
	/** The transfer example with a speed-controlled pump (minimum speed 85 %). */
	function controlled(): Project {
		const base = pumpTransferExample();
		const pump = base.components[1]!;
		if (pump.type === 'pump') pump.control = { mode: 'flow', setpoint: 0.015, minSpeed: 0.85 };
		return base;
	}

	it('puts a rule of a whole element at the value it rejects, not at the element’s valid values', () => {
		const overrides: Override[] = [
			{ kind: 'component', componentId: 'P1', field: 'control.setpoint', value: 0.02 },
			{ kind: 'component', componentId: 'P1', field: 'speed', value: 0.8 },
			{ kind: 'pipe', connectionId: 'L2', pipeIndex: 0, field: 'length', value: 50 },
			{
				kind: 'pipe',
				connectionId: 'L2',
				pipeIndex: 0,
				field: 'spec',
				value: { materialId: 'custom' }
			}
		];
		const project = withScenarios(controlled(), [{ id: 'S1', name: 'Winter', overrides }]);
		const problems = scenarioProblems(project, 'S1');
		expect(problems.map((p) => p.index)).toEqual([1, 3]);
		// With the valid values alone there is nothing to report.
		const valid = withScenarios(controlled(), [
			{ id: 'S1', name: 'Winter', overrides: [overrides[0]!, overrides[2]!] }
		]);
		expect(scenarioProblems(valid, 'S1')).toEqual([]);
	});

	it('gives a fluid with the values that define it', () => {
		const project = pumpTransferExample();
		const text = (value: unknown) =>
			changeValueText(project, { kind: 'project', field: 'fluid', value }, value, SI_UNITS);
		const v = (si: number, category: Parameters<typeof formatValue>[1], absolute = false) =>
			formatValue(si, category, SI_UNITS, 4, { absolute });
		expect(
			text({
				kind: 'custom',
				name: 'Brine',
				temperature: 278.15,
				density: 1100,
				dynamicViscosity: 0.002,
				vaporPressure: 2339
			})
		).toBe(
			`Brine (custom) at ${v(278.15, 'temperature')}, density ${v(1100, 'density')}, dynamic viscosity ${v(0.002, 'viscosity')}, vapor pressure ${v(2339, 'pressure', true)}`
		);
		expect(
			text({
				kind: 'builtin',
				fluidId: 'water',
				temperature: 293.15,
				overrides: { density: 1100, vaporPressure: 2000 }
			})
		).toBe(
			`Water, at ${v(293.15, 'temperature')}, density override ${v(1100, 'density')}, vapor pressure override ${v(2000, 'pressure', true)}`
		);
		// Two custom fluids of one name differ in their values.
		const custom = { kind: 'custom', name: 'test liquid', density: 998, dynamicViscosity: 0.001 };
		expect(text(custom)).not.toBe(text({ ...custom, density: 1200 }));
	});
});

describe('the words of every allow-listed number (exhaustiveness, equipment-pressure-drop.md §7.6)', () => {
	/**
	 * One component of every kind (the values with no default as a user enters them), a pump with
	 * flow control, an equipment item rated by a Cv and an orifice plate with an entered C, so every
	 * allow-listed number is held.
	 */
	function samples(): Project {
		const base = pumpTransferExample();
		const components = COMPONENT_KINDS.reduce<Project['components']>((list, kind) => {
			const sofar = { ...base, components: [...base.components, ...list] };
			return [...list, createComponent(kind, sofar, enteredFor(kind))];
		}, []);
		const all = [...base.components, ...components];
		const sofar = { ...base, components: all };
		const pump = createComponent('pump', sofar);
		const controlled = {
			...pump,
			curveId: base.pumpLibrary[0]!.id,
			control: { mode: 'flow', setpoint: 0.012, minSpeed: 0.5 }
		} as Component;
		const cv = createComponent(
			'equipment',
			{ ...sofar, components: [...all, controlled] },
			{
				rating: { kind: 'Cv', value: 80 }
			}
		);
		const plate = {
			...createComponent(
				'orifice',
				{ ...sofar, components: [...all, controlled, cv] },
				{ boreDiameter: 0.05 }
			),
			dischargeCoefficient: 0.6
		} as Component;
		return { ...base, components: [...all, controlled, cv, plate] };
	}

	/** Whether a published schema property is a number (directly or as anyOf's number). */
	function numeric(schema: string, key: string): boolean {
		const property = (
			openapi.components.schemas as unknown as Record<
				string,
				{ properties?: Record<string, { type?: string; anyOf?: { type?: string }[] }> }
			>
		)[schema]?.properties?.[key];
		const types = [property?.type, ...(property?.anyOf ?? []).map((a) => a.type)];
		return types.includes('number') || types.includes('integer');
	}

	it('has a label, a value text with its unit, an export category and a variable spec', () => {
		const project = samples();
		const expected = new Set<string>();
		for (const [target, entries] of Object.entries(OVERRIDE_FIELDS)) {
			for (const [field, entry] of Object.entries(entries)) {
				if (!entry.keys.length && numeric(entry.schema, entry.path[entry.path.length - 1]!)) {
					expected.add(`${target}.${field}`);
				}
			}
		}
		const checked = new Set<string>();
		const targets: { schema: string; target: ChangeTarget; component?: Component }[] = [
			...project.components.map((component) => ({
				schema: componentSchemaName(component)!,
				target: { kind: 'component', componentId: component.id } as ChangeTarget,
				component
			})),
			{ schema: 'PipeDefinition', target: { kind: 'pipe', connectionId: 'L1', pipeIndex: 0 } },
			{ schema: 'Project', target: { kind: 'project' } }
		];
		for (const { schema, target, component } of targets) {
			for (const field of Object.keys(OVERRIDE_FIELDS[schema] ?? {})) {
				const value = valueOf(project, target, field);
				if (typeof value !== 'number') continue;
				const where = `${schema}.${field}`;
				checked.add(where);
				const override = makeOverride(target, field, value);
				// A label: never a raw path (a dot, or a camelCase join such as "pressureLoss").
				const label = changeFieldLabel(project, override);
				const own = component ? fieldLabelFor(component, field) : label;
				for (const text of [label, own]) expect(text, where).not.toMatch(/\.|[a-z][A-Z]/);
				// The variable spec, the value text and the export category agree on one unit.
				const spec = variableSpec(project, { target, field });
				const text = changeValueText(project, override, value, SI_UNITS);
				const category = changeCategory(project, {
					index: 0,
					override,
					state: 'applied',
					value,
					baseValue: value,
					unit: '',
					message: ''
				});
				if (field === 'rating.value') {
					// The named exception: a coefficient as entered, written with its kind.
					expect(spec, where).toEqual({ category: 'dimensionless', options: {}, prefix: 'Cv ' });
					expect(text, where).toBe('Cv 80');
					expect(category, where).toBeNull();
					continue;
				}
				if (field === 'dischargeCoefficient') {
					// The other named exception: ISO 5167-2's C as entered, a pure number with no unit
					// (orifice-plate.md §5.4: dimensionless in the export).
					expect(spec, where).toEqual({ category: 'dimensionless', options: {} });
					expect(text, where).toBe('0.6');
					expect(category, where).toEqual({ category: 'dimensionless', options: {} });
					continue;
				}
				expect(spec.category, where).not.toBe('dimensionless');
				expect(category, where).toEqual({ category: spec.category, options: spec.options });
				const unit = unitLabel(spec.category, displayUnit(spec.category, SI_UNITS), spec.options);
				expect(unit, where).not.toBe('');
				expect(text, where).toContain(unit);
			}
		}
		expect([...checked].sort()).toEqual([...expected].sort());
		// Every number goal seek varies is one of them, or a valve's coefficient (resistance).
		for (const [schema, fields] of Object.entries(GOAL_VARIABLE_FIELDS)) {
			for (const field of Object.keys(fields)) {
				if (field === 'resistance') continue;
				expect(expected, `${schema}.${field}`).toContain(`${schema}.${field}`);
			}
		}
	});
});
